  const prior=byAuth[0]||byGate[0]||null;if(prior)return canonicalStringify(prior)===canonicalStringify(evidence)?result(OUTCOMES.ALREADY_SATISFIED,"same exact authorization already consumed for this gate",prior):result(OUTCOMES.CONFLICT,"authorization or gate already consumed differently");let stored;try{stored=consumptionLedger.commit(evidence);}catch(_){return result(OUTCOMES.CONFLICT,"consumption ledger commit conflict");}if(canonicalStringify(stored)!==canonicalStringify(evidence))return result(OUTCOMES.CONFLICT,"consumption ledger did not preserve exact evidence");return result(OUTCOMES.SATISFIED,null,evidence);
